begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id) select ('a9000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid from generate_series(1,11)i;
insert into profiles(id,display_name,consented_at) select id,'Fixture',now() from auth.users where id::text like 'a9000000-%';
insert into families(id,name,residence_country_code,residence_locality,residence_city) select ('b9000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Fixture','KR','Fixture neighborhood',case when i=11 then 'Other city' else 'Fixture city' end from generate_series(1,11)i;
insert into family_members(family_id,user_id,role,relationship) select ('b9000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,('a9000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'owner','father' from generate_series(1,11)i;
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select neighborhood_feed('b9000000-0000-4000-8000-000000000001','boards')$$,'42501','not_open','closed feature cannot be accessed');
select lives_ok($$select request_neighborhood('b9000000-0000-4000-8000-000000000001','boards')$$,'family requests feature');
select lives_ok($$select request_neighborhood('b9000000-0000-4000-8000-000000000001','boards')$$,'repeated click is idempotent');
select is((select families from neighborhood_status('b9000000-0000-4000-8000-000000000001') where feature='boards'),1::bigint,'one family counted once');
select throws_ok($$select request_neighborhood('b9000000-0000-4000-8000-000000000002','boards')$$,'42501','forbidden','cannot submit for another family');
reset role;
do $$ begin for i in 2..9 loop
 perform set_config('request.jwt.claims',jsonb_build_object('sub','a9000000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
 perform request_neighborhood(('b9000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'boards');
end loop; end $$;
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select ok(not (select opened from neighborhood_status('b9000000-0000-4000-8000-000000000001') where feature='boards'),'nine families stays closed');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000010","role":"authenticated"}',true);
select request_neighborhood('b9000000-0000-4000-8000-000000000010','boards');
select ok((select opened from neighborhood_status('b9000000-0000-4000-8000-000000000010') where feature='boards'),'tenth family opens automatically');
select ok((select opened from neighborhood_status('b9000000-0000-4000-8000-000000000010') where feature='market'),'one neighborhood request opens market too');
select lives_ok($$select save_neighborhood_post('b9000000-0000-4000-8000-000000000010','boards','First post','Local story')$$,'opened feature accepts posts');
select is((select count(*) from neighborhood_feed('b9000000-0000-4000-8000-000000000010','boards')),1::bigint,'local post visible');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000011","role":"authenticated"}',true);
select throws_ok($$select neighborhood_feed('b9000000-0000-4000-8000-000000000011','boards')$$,'42501','not_open','another region stays closed');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select save_global_residence('b9000000-0000-4000-8000-000000000001','US','California','Springfield','Downtown',0)$$,'owner registers overseas place');
select request_neighborhood_family('b9000000-0000-4000-8000-000000000001');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select lives_ok($$select save_global_residence('b9000000-0000-4000-8000-000000000002','US',' california ',' springfield ',' downtown ',0)$$,'another owner reuses normalized place');
select is((select count(*) from global_residence_places where country_code='US' and province_key='california' and city_key='springfield' and locality_key='downtown'),1::bigint,'case and spaces do not duplicate places');
select request_neighborhood_family('b9000000-0000-4000-8000-000000000002');
select is((select families from neighborhood_status('b9000000-0000-4000-8000-000000000002') where feature='boards'),2::bigint,'overseas families grouped by shared place');
select is((select families from neighborhood_status('b9000000-0000-4000-8000-000000000002') where feature='support'),2::bigint,'same request counts for all services');
select ok(exists(select 1 from global_place_options('US','','') where province='California'),'registered province selectable by others');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select save_global_residence('b9000000-0000-4000-8000-000000000003','US','Massachusetts','Springfield','Downtown',0);
select is((select families from neighborhood_status('b9000000-0000-4000-8000-000000000003') where feature='boards'),0::bigint,'same city name in different state is isolated');
select throws_ok($$select save_global_residence('b9000000-0000-4000-8000-000000000003','US','','City','Area',1)$$,'22023','region required','three overseas levels required');
select * from finish();
rollback;
